window.kbPageData["views/entry/k-260f7988a0f059cc"] = {"key":"entry/k-260f7988a0f059cc","state":{"route":"entry/k-260f7988a0f059cc"},"node":{"id":"k-260f7988a0f059cc","mode":"k","title":"对基础教育工作作出重要指示（7 月）","type":"事实与事件","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["社会治理"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"对基础教育工作作出重要指示（7 月）","slug":"38d80c5aaebf"}],"directorySummary":"考点三十一 对基础教育工作作出重要指示（7 月）\n指出，党中央把基础教育作为基础性、先导性工作来抓，基础教育长足发展为建设教育强国提\n供有力支撑。\n新征程上要落实立德树人根本任务，用党的创新理论铸魂育人，培养德智体美劳全面发展的社\n会主义建设者和接班人；遵循教育规律，落实健康第一教育理念，促进广大学…","sources":[{"id":"e045025444cd31f3","label":"对基础教育工作作出重要指示（7 月）","topic":"重要会议讲话","category":"时政","text":"考点三十一 对基础教育工作作出重要指示（7 月）\n指出，党中央把基础教育作为基础性、先导性工作来抓，基础教育长足发展为建设教育强国提\n供有力支撑。\n新征程上要落实立德树人根本任务，用党的创新理论铸魂育人，培养德智体美劳全面发展的社\n会主义建设者和接班人；遵循教育规律，落实健康第一教育理念，促进广大学生身心健康；推\n进基础教育扩优提质，牢牢守住教育公平底线；弘扬教育家精神，加强师德师风建设；推动学\n校（主阵地）、家庭（第一课堂）、社会（大课堂）同向发力。\n我国基础教育整体已达世界高收入国家平均水平，建成世界上规模最大且有质量的基础教育体\n系，多项关键指标处于全球领先位置。","source":{"doc":"4e539a366dce19555ccf","first":7,"last":8,"page":7,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-260f7988a0f059cc":[]}};
